const fs = require('fs');

function main() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function readInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let res = 0;
        while (offset < buffer.length && buffer[offset] > 32) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res;
    }

    const N = readInt();
    if (N === null) return;
    const M = readInt();
    const T = new Int32Array(M);
    for (let i = 0; i < M; i++) {
        T[i] = readInt();
    }

    const maxGuests = 10000;
    const result = new Int32Array(maxGuests);
    let count = 0;

    for (let p = 1; count < maxGuests; p++) {
        let cur = p;
        let exceeded = false;
        for (let i = M - 1; i >= 0; i--) {
            cur += Math.floor((cur - 1) / (T[i] - 1));
            if (cur > N) {
                exceeded = true;
                break;
            }
        }
        if (exceeded) {
            break;
        }
        result[count++] = cur;
    }

    let out = '';
    for (let i = 0; i < count; i++) {
        out += result[i] + '\n';
        if (out.length > 65536) {
            process.stdout.write(out);
            out = '';
        }
    }
    if (out.length > 0) {
        process.stdout.write(out);
    }
}

main();
